var zonesFC = ee.FeatureCollection(ZONES.map(function (z) {
  return ee.Feature(ee.Geometry.MultiPolygon(z.polys.map(function (r) { return [r]; })), {zone: z.zone});
}));
var chirps = ee.ImageCollection('UCSB-CHC/CHIRPS/V3/DAILY_SAT').select('precipitation');

// ---------------------------------------------------------------- 1. CHIRPS zone daily
var perDay = chirps.filterDate('2014-01-01', '2026-01-01').map(function (img) {
  var date = img.date().format('YYYY-MM-dd');
  return img.reduceRegions({collection: zonesFC, reducer: ee.Reducer.mean(), scale: 5566})
    .map(function (f) { return ee.Feature(null, {date: date, zone: f.get('zone'), rain_mm: f.get('mean')}); });
}).flatten();
Export.table.toDrive({collection: perDay, description: 'fg_chirps_zone_daily', folder: FOLDER,
  fileFormat: 'CSV', selectors: ['date', 'zone', 'rain_mm']});

// ---------------------------------------------------------------- 2. static layers (30 m)
var dem = ee.Image('USGS/SRTMGL1_003').select('elevation');
var wc = ee.ImageCollection('ESA/WorldCover/v200').first().select('Map')
  .reduceResolution({reducer: ee.Reducer.mode(), maxPixels: 64}).reproject({crs: CRS, scale: 30});
var jrc = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select(['occurrence', 'seasonality']).unmask(0);
Export.image.toDrive({image: dem.toInt16(), description: 'fg_dem_srtm30', folder: FOLDER, region: region,
  scale: 30, crs: CRS, maxPixels: 1e10});
Export.image.toDrive({image: wc.toUint8(), description: 'fg_worldcover2021', folder: FOLDER, region: region,
  scale: 30, crs: CRS, maxPixels: 1e10});
Export.image.toDrive({image: jrc.toUint8(), description: 'fg_jrc_water', folder: FOLDER, region: region,
  scale: 30, crs: CRS, maxPixels: 1e10});

// ---------------------------------------------------------------- 3. Sentinel-1 event labels
var slope = ee.Terrain.slope(dem);
var permanent = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('seasonality').unmask(0).gte(10);
var s1 = ee.ImageCollection('COPERNICUS/S1_GRD').filterBounds(aoi)
  .filter(ee.Filter.eq('instrumentMode', 'IW'))
  .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV')).select('VV');

function candidates(peak) {
  return s1.filterDate(peak.advance(-MAX_DAYS, 'day'), peak.advance(MAX_DAYS + 1, 'day'))
    .map(function (i) { return i.set('dt', ee.Number(i.date().difference(peak, 'day')).abs()); }).sort('dt');
}

function eventBands(ev) {
  var peak = ee.Date(ev.peak);
  var cand = candidates(peak);
  var first = ee.Image(cand.first());
  var orbit = first.get('relativeOrbitNumber_start');
  var day = ee.Date(first.date().format('YYYY-MM-dd'));
  var post = cand.filter(ee.Filter.eq('relativeOrbitNumber_start', orbit))
    .filterDate(day, day.advance(1, 'day')).mosaic().focal_median(50, 'circle', 'meters');
  var yr = peak.get('year');
  var pre = s1.filter(ee.Filter.eq('relativeOrbitNumber_start', orbit))
    .filterDate(ee.Date.fromYMD(yr, 1, 1), ee.Date.fromYMD(yr, 5, 1)).median().focal_median(50, 'circle', 'meters');
  var water = post.lt(WATER_DB);
  var flood = post.subtract(pre).lt(-DIFF_DB).and(water).and(permanent.not()).and(slope.lt(5)).unmask(0);
  var valid = post.mask().and(pre.mask()).unmask(0);
  var toGrid = function (img) {   // 10 m fractions -> exact 100 m grid
    // set an explicit 10 m projection: band math with unmask()/JRC/slope drops the default projection
    return img.toFloat().setDefaultProjection({crs: CRS, scale: 10})
      .reduceResolution({reducer: ee.Reducer.mean(), maxPixels: 1024})
      .reproject({crs: CRS, crsTransform: GRID.crsTransform});
  };
  return toGrid(flood).multiply(100).round().rename(ev.id + '_flood')
    .addBands(toGrid(valid).multiply(100).round().rename(ev.id + '_valid'));
}

// CHIRPS totals ending the DAY BEFORE the S1 date, on the native 0.05 deg grid (tiny export)
function eventRain(ev) {
  var day = ee.Date(ee.Image(candidates(ee.Date(ev.peak)).first()).date().format('YYYY-MM-dd'));
  var r = function (n) { return chirps.filterDate(day.advance(-n, 'day'), day).sum(); };
  return r(1).rename(ev.id + '_r1').addBands(r(3).rename(ev.id + '_r3')).addBands(r(7).rename(ev.id + '_r7'));
}

function eventMeta(ev) {
  var cand = candidates(ee.Date(ev.peak));
  var f = ee.Feature(null, {event_id: ev.id, peak_date: ev.peak, n_candidates: cand.size()});
  var im = ee.Image(cand.first());
  return ee.Feature(ee.Algorithms.If(cand.size().gt(0),
    f.set({s1_date: im.date().format('YYYY-MM-dd'), days_from_peak: im.get('dt'),
           relative_orbit: im.get('relativeOrbitNumber_start'), pass: im.get('orbitProperties_pass')}),
    f.set({s1_date: '', days_from_peak: -1})));
}

var meta = ee.FeatureCollection(EVENTS.map(eventMeta));
Export.table.toDrive({collection: meta, description: 'fg_s1_event_dates', folder: FOLDER, fileFormat: 'CSV'});

// events with a scene in the window only (client-side list evaluated once)
var withScene = meta.filter(ee.Filter.gt('n_candidates', 0)).aggregate_array('event_id').getInfo();
var usable = EVENTS.filter(function (e) { return withScene.indexOf(e.id) >= 0; });
print('Events with a Sentinel-1 scene within +/-' + MAX_DAYS + ' days:', usable.length, 'of', EVENTS.length);
for (var c = 0; c * CHUNK < usable.length; c++) {
  var part = usable.slice(c * CHUNK, (c + 1) * CHUNK);
  var img = eventBands(part[0]);
  for (var k = 1; k < part.length; k++) { img = img.addBands(eventBands(part[k])); }
  Export.image.toDrive({image: img.toUint8(), description: 'fg_events_' + String.fromCharCode(97 + c),
    folder: FOLDER, crs: CRS, crsTransform: GRID.crsTransform,
    dimensions: GRID.w + 'x' + GRID.h, maxPixels: 1e10});
}

var rainImg = eventRain(usable[0]);
for (var q = 1; q < usable.length; q++) { rainImg = rainImg.addBands(eventRain(usable[q])); }
Export.image.toDrive({image: rainImg.toFloat(), description: 'fg_events_rain', folder: FOLDER,
  region: region, crs: 'EPSG:4326', crsTransform: [0.05, 0, -180, 0, -0.05, 50], maxPixels: 1e9});

// ---------------------------------------------------------------- visual check
Map.centerObject(aoi, 10);
var big = eventBands({id: 'E20220817', peak: '2022-08-17'});
Map.addLayer(big.select('E20220817_flood'), {min: 0, max: 100, palette: ['white', '#d7301f']}, 'flood % 17-08-2022');
Map.addLayer(ee.Image().paint(aoi, 0, 2), {palette: ['black']}, 'AOI');
print('Meta (check s1_date / days_from_peak):', meta.limit(60));
